#include <windows.h>
#include <algorithm>
#include <iostream>
#include <stdexcept>
#include <string>
namespace {
void require(bool value,const char* text){if(!value)throw std::runtime_error(text);}
int fixture(const char* readyName,const char* stopName){auto ready=OpenEventA(EVENT_MODIFY_STATE,FALSE,readyName),stop=OpenEventA(SYNCHRONIZE,FALSE,stopName);if(!ready||!stop)return 10;WNDCLASSW wc{};wc.lpfnWndProc=DefWindowProcW;wc.hInstance=GetModuleHandleW(nullptr);wc.lpszClassName=L"Respawn001";if(!RegisterClassW(&wc))return 11;auto minimized=CreateWindowW(L"STATIC",L"Apex Legends picker fixture",WS_OVERLAPPEDWINDOW,100,100,640,480,nullptr,nullptr,wc.hInstance,nullptr);auto renamed=CreateWindowW(wc.lpszClassName,L"Renamed game fixture",WS_OVERLAPPEDWINDOW,150,150,640,480,nullptr,nullptr,wc.hInstance,nullptr);auto unrelated=CreateWindowW(L"STATIC",L"Unrelated notes fixture",WS_OVERLAPPEDWINDOW,200,200,640,480,nullptr,nullptr,wc.hInstance,nullptr);if(!minimized||!renamed||!unrelated)return 12;ShowWindow(minimized,SW_SHOWMINNOACTIVE);ShowWindow(renamed,SW_SHOWNOACTIVATE);ShowWindow(unrelated,SW_SHOWNOACTIVATE);SetEvent(ready);for(;;){auto wait=MsgWaitForMultipleObjects(1,&stop,FALSE,10000,QS_ALLINPUT);if(wait==WAIT_OBJECT_0)break;if(wait==WAIT_FAILED)return 13;MSG msg{};while(PeekMessageW(&msg,nullptr,0,0,PM_REMOVE)){TranslateMessage(&msg);DispatchMessageW(&msg);}}DestroyWindow(minimized);DestroyWindow(renamed);DestroyWindow(unrelated);UnregisterClassW(wc.lpszClassName,wc.hInstance);CloseHandle(ready);CloseHandle(stop);return 0;}
struct Child{HANDLE ready=nullptr,stop=nullptr;PROCESS_INFORMATION process{};~Child(){if(stop)SetEvent(stop);if(process.hProcess){if(WaitForSingleObject(process.hProcess,5000)!=WAIT_OBJECT_0)TerminateProcess(process.hProcess,14);CloseHandle(process.hProcess);}if(process.hThread)CloseHandle(process.hThread);if(ready)CloseHandle(ready);if(stop)CloseHandle(stop);}};
}
int main(int argc,char** argv){if(argc==4&&std::string(argv[1])=="--fixture")return fixture(argv[2],argv[3]);try{apex::TrackingWindow bad;auto state=apex::inspectTrackingWindow(bad);std::string error;require(!state.valid&&!apex::sendTrackingMovement(bad,1,1,error)&&!error.empty(),"Invalid window reached mouse output");Child child;auto suffix=std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64());auto readyName="Local\\ApexPickerReady-"+suffix,stopName="Local\\ApexPickerStop-"+suffix;child.ready=CreateEventA(nullptr,TRUE,FALSE,readyName.c_str());child.stop=CreateEventA(nullptr,TRUE,FALSE,stopName.c_str());require(child.ready&&child.stop,"Fixture events failed");wchar_t path[32768]{};require(GetModuleFileNameW(nullptr,path,32768)>0,"Fixture executable path unavailable");std::string arguments=" --fixture "+readyName+" "+stopName;std::wstring command=L"\""+std::wstring(path)+L"\""+std::wstring(arguments.begin(),arguments.end());STARTUPINFOW startup{};startup.cb=sizeof(startup);require(CreateProcessW(path,command.data(),nullptr,nullptr,FALSE,0,nullptr,nullptr,&startup,&child.process)!=FALSE,"Fixture child failed");require(WaitForSingleObject(child.ready,10000)==WAIT_OBJECT_0,"Fixture windows not ready");auto windows=apex::trackingWindows();bool minimized=false,renamed=false;for(const auto& w:windows){require(w.handle&&w.process!=GetCurrentProcessId()&&!w.title.empty(),"Own/invalid window enumerated");if(w.process!=child.process.dwProcessId)continue;if(w.title=="Apex Legends picker fixture"){minimized=true;auto check=apex::inspectTrackingWindow(w);require(!check.valid&&check.status.find("minimized")!=std::string::npos,"Minimized window did not explain restore requirement");}else if(w.title=="Renamed game fixture"){renamed=true;require(apex::inspectTrackingWindow(w).valid,"Respawn001 fallback not selectable");auto wrong=w;++wrong.process;require(!apex::inspectTrackingWindow(wrong).valid,"PID mismatch not rejected");}else require(false,"Unrelated window was recognized as Apex");}require(minimized&&renamed,"Picker excluded minimized game or native class fallback");std::cout<<"PASS actual child-window enumeration: minimized Apex remains selectable with restore reason, Respawn001 class fallback, unrelated/own windows excluded and invalid/PID-mismatch guards preserved; no Apex/input-acceptance claim\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
